// ২. ক্লাসের বডি (Class Body)
private android.widget.ListView listView;
private android.widget.ProgressBar progressBar;
private MyAdapter myAdapter;
private String pendingPkg = "";

private void checkVpnAndStart() {
    android.content.Intent intent = android.net.VpnService.prepare(this);
    if (intent != null) {
        startActivityForResult(intent, 101);
    } else {
        showConfirmDialog(pendingPkg);
    }
}

@Override
protected void onActivityResult(int req, int res, android.content.Intent d) {
    if (req == 101 && res == RESULT_OK) {
        showConfirmDialog(pendingPkg);
    }
}

private void showConfirmDialog(final String pkg) {
    String name = ""; 
    try { name = getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(pkg, 0)).toString(); } catch(Exception e) { name = pkg; }

    new android.app.AlertDialog.Builder(this)
        .setTitle("Block Internet?")
        .setMessage("Do you want to block internet for " + name + "?")
        .setPositiveButton("Yes", (d, w) -> {
            // নতুন রুল তৈরি হচ্ছে (ডিফল্ট 0m অর্থাৎ আনলিমিটেড ব্লক)
            CycleService.appRules.put(pkg, new CycleService.AppRule());
            updateService();
        })
        .setNegativeButton("No", (d, w) -> {
            if (myAdapter != null) myAdapter.notifyDataSetChanged();
        })
        .setCancelable(false)
        .show();
}

private void showTimerDialog(final String pkg, String appName) {
    android.widget.ScrollView scroll = new android.widget.ScrollView(this);
    android.widget.LinearLayout base = new android.widget.LinearLayout(this);
    base.setOrientation(1); base.setPadding(50, 40, 50, 40);
    scroll.addView(base);

    // Section 1: Allow Time
    android.widget.TextView t1 = new android.widget.TextView(this);
    t1.setText("This app can use internet.");
    t1.setTextSize(16); t1.setTextColor(0xFF000000); t1.setTypeface(null, android.graphics.Typeface.BOLD);
    base.addView(t1);

    final android.widget.RadioGroup rgAllow = new android.widget.RadioGroup(this);
    String[] allowLabels = {"1m", "5m", "10m", "15m", "30m"};
    long[] allowMs = {60000, 300000, 600000, 900000, 1800000};
    for (int i = 0; i < allowLabels.length; i++) {
        android.widget.RadioButton rb = new android.widget.RadioButton(this);
        rb.setText(allowLabels[i]); rb.setId(100 + i); rgAllow.addView(rb);
        if (allowLabels[i].equals("5m")) rb.setChecked(true); // Default
    }
    base.addView(rgAllow);

    // Section 2: Block Time
    android.widget.TextView t2 = new android.widget.TextView(this);
    t2.setText("\nThe app will be blocked from using internet.");
    t2.setTextSize(16); t2.setTextColor(0xFF000000); t2.setTypeface(null, android.graphics.Typeface.BOLD);
    base.addView(t2);

    final android.widget.RadioGroup rgBlock = new android.widget.RadioGroup(this);
    String[] blockLabels = {"1m", "5m", "10m", "15m", "30m", "1h"};
    long[] blockMs = {60000, 300000, 600000, 900000, 1800000, 3600000};
    for (int i = 0; i < blockLabels.length; i++) {
        android.widget.RadioButton rb = new android.widget.RadioButton(this);
        rb.setText(blockLabels[i]); rb.setId(200 + i); rgBlock.addView(rb);
        if (blockLabels[i].equals("5m")) rb.setChecked(true); // Default
    }
    base.addView(rgBlock);

    // Load existing settings if any
    CycleService.AppRule rule = CycleService.appRules.get(pkg);
    if (rule != null) {
        for(int i=0; i<allowLabels.length; i++) if(allowLabels[i].equals(rule.allowStr)) rgAllow.check(100+i);
        for(int i=0; i<blockLabels.length; i++) if(blockLabels[i].equals(rule.blockStr)) rgBlock.check(200+i);
    }

    new android.app.AlertDialog.Builder(this)
        .setTitle("Timer for " + appName)
        .setView(scroll)
        .setPositiveButton("Apply", (d, w) -> {
            int aId = rgAllow.getCheckedRadioButtonId() - 100;
            int bId = rgBlock.getCheckedRadioButtonId() - 200;

            if (rule != null) {
                rule.allowTimeMs = (aId >= 0 && aId < allowMs.length) ? allowMs[aId] : 300000;
                rule.blockTimeMs = (bId >= 0 && bId < blockMs.length) ? blockMs[bId] : 300000;
                rule.allowStr = (aId >= 0 && aId < allowLabels.length) ? allowLabels[aId] : "5m";
                rule.blockStr = (bId >= 0 && bId < blockLabels.length) ? blockLabels[bId] : "5m";

                // Apply চাপলেই ব্লক ফেইজ থেকে সাইকেল শুরু হবে
                rule.isCurrentlyBlocked = false; 
                rule.phaseStartTime = System.currentTimeMillis();
            }
            updateService();
        })
        .setNegativeButton("Cancel", null)
        .show();
}

private void updateService() {
    android.content.Intent it = new android.content.Intent(this, CycleService.class);
    it.setAction(CycleService.appRules.isEmpty() ? "STOP" : "START");
    startService(it);
    if (myAdapter != null) myAdapter.notifyDataSetChanged();
}

private void loadAppList() {
    progressBar.setVisibility(0);
    new Thread(() -> {
        android.content.pm.PackageManager pm = getPackageManager();
        android.content.Intent i = new android.content.Intent("android.intent.action.MAIN").addCategory("android.intent.category.LAUNCHER");
        java.util.List<android.content.pm.ResolveInfo> list = pm.queryIntentActivities(i, 0);
        java.util.Collections.sort(list, new android.content.pm.ResolveInfo.DisplayNameComparator(pm));
        final java.util.ArrayList<java.util.HashMap<String, Object>> data = new java.util.ArrayList<>();
        for (android.content.pm.ResolveInfo r : list) {
            if (r.activityInfo.packageName.equals(getPackageName())) continue;
            java.util.HashMap<String, Object> m = new java.util.HashMap<>();
            m.put("n", pm.getApplicationLabel(r.activityInfo.applicationInfo).toString());
            m.put("p", r.activityInfo.packageName);
            m.put("i", pm.getApplicationIcon(r.activityInfo.applicationInfo));
            data.add(m);
        }
        runOnUiThread(() -> { progressBar.setVisibility(8); myAdapter = new MyAdapter(data); listView.setAdapter(myAdapter); });
    }).start();
}

class MyAdapter extends android.widget.BaseAdapter {
    java.util.ArrayList<java.util.HashMap<String, Object>> _d;
    MyAdapter(java.util.ArrayList<java.util.HashMap<String, Object>> d) { _d = d; }
    @Override public int getCount() { return _d.size(); }
    @Override public Object getItem(int i) { return _d.get(i); }
    @Override public long getItemId(int i) { return i; }
    @Override public android.view.View getView(int i, android.view.View v, android.view.ViewGroup p) {
        if (v == null) {
            android.widget.LinearLayout root = new android.widget.LinearLayout(MainActivity.this);
            root.setOrientation(1); // Vertical

            android.widget.LinearLayout top = new android.widget.LinearLayout(MainActivity.this);
            top.setPadding(25, 30, 25, 10); top.setGravity(16);
            android.widget.ImageView img = new android.widget.ImageView(MainActivity.this); top.addView(img, 110, 110);
            android.widget.TextView t = new android.widget.TextView(MainActivity.this); t.setPadding(35, 0, 0, 0); t.setTextSize(16);
            top.addView(t, new android.widget.LinearLayout.LayoutParams(0, -2, 1f));
            android.widget.Switch s = new android.widget.Switch(MainActivity.this); top.addView(s);

            android.widget.TextView timerTxt = new android.widget.TextView(MainActivity.this);
            timerTxt.setPadding(170, 0, 25, 30); timerTxt.setTextSize(14); 
            timerTxt.setTextColor(android.graphics.Color.parseColor("#007BFF")); // Blue Color
            timerTxt.setVisibility(android.view.View.GONE);

            root.addView(top); root.addView(timerTxt); v = root;
        }

        java.util.HashMap<String, Object> m = _d.get(i);
        final String pkg = m.get("p").toString();
        final String name = m.get("n").toString();

        android.widget.LinearLayout root = (android.widget.LinearLayout)v;
        android.widget.LinearLayout top = (android.widget.LinearLayout)root.getChildAt(0);
        android.widget.ImageView img = (android.widget.ImageView)top.getChildAt(0);
        android.widget.TextView txtName = (android.widget.TextView)top.getChildAt(1);
        android.widget.Switch sw = (android.widget.Switch)top.getChildAt(2);
        android.widget.TextView timerTxt = (android.widget.TextView)root.getChildAt(1);

        txtName.setText(name);
        img.setImageDrawable((android.graphics.drawable.Drawable)m.get("i"));

        sw.setOnCheckedChangeListener(null);
        boolean isSelected = CycleService.appRules.containsKey(pkg);
        sw.setChecked(isSelected);

        if (isSelected) {
            timerTxt.setVisibility(android.view.View.VISIBLE);
            CycleService.AppRule rule = CycleService.appRules.get(pkg);
            timerTxt.setText("Blocked in " + rule.blockStr + ".\nCan use " + rule.allowStr + ".");
            timerTxt.setOnClickListener(v_click -> showTimerDialog(pkg, name));
        } else {
            timerTxt.setVisibility(android.view.View.GONE);
        }

        sw.setOnClickListener(view -> {
            if (CycleService.appRules.containsKey(pkg)) {
                CycleService.appRules.remove(pkg);
                updateService();
            } else {
                sw.setChecked(false);
                pendingPkg = pkg;
                checkVpnAndStart();
            }
        });
        return v;
    }
}

private void showMyLogs() {}

public static class CycleService extends android.net.VpnService {
    public static class AppRule {
        public long blockTimeMs = 0; // 0 মানে আনলিমিটেড ব্লক
        public long allowTimeMs = 0;
        public long phaseStartTime = 0;
        public boolean isCurrentlyBlocked = true;
        public String blockStr = "Unlimited";
        public String allowStr = "0m";
    }

    private android.os.ParcelFileDescriptor vpn = null;
    public static java.util.concurrent.ConcurrentHashMap<String, AppRule> appRules = new java.util.concurrent.ConcurrentHashMap<>();
    private Thread timerThread;
    private boolean isRunning = false;

    @Override
    public int onStartCommand(android.content.Intent it, int f, int id) {
        if (it != null && "STOP".equals(it.getAction())) { stopVpn(); return START_NOT_STICKY; }
        if (appRules.isEmpty()) { stopVpn(); return START_NOT_STICKY; }

        establishVpn();
        startTimerThread();
        return START_STICKY;
    }

    private void startTimerThread() {
        if (isRunning) return;
        isRunning = true;
        timerThread = new Thread(() -> {
            while (isRunning) {
                boolean needsRebuild = false;
                long now = System.currentTimeMillis();
                for (String pkg : appRules.keySet()) {
                    AppRule rule = appRules.get(pkg);
                    if (rule.blockTimeMs > 0 && rule.allowTimeMs > 0) { // যদি টাইমার সেট করা থাকে
                        if (rule.isCurrentlyBlocked) {
                            if (now - rule.phaseStartTime >= rule.blockTimeMs) {
                                rule.isCurrentlyBlocked = false; // ব্লক শেষ, আনব্লক শুরু
                                rule.phaseStartTime = now;
                                needsRebuild = true;
                            }
                        } else {
                            if (now - rule.phaseStartTime >= rule.allowTimeMs) {
                                rule.isCurrentlyBlocked = true; // আনব্লক শেষ, আবার ব্লক শুরু
                                rule.phaseStartTime = now;
                                needsRebuild = true;
                            }
                        }
                    }
                }
                if (needsRebuild) {
                    establishVpn(); // সাইকেল বদলালে ভিপিএন আপডেট হবে
                }
                try { Thread.sleep(1000); } catch(Exception e) {} // প্রতি ১ সেকেন্ডে চেক করবে
            }
        });
        timerThread.start();
    }

    private void establishVpn() {
        try {
            java.util.ArrayList<String> activeBlocks = new java.util.ArrayList<>();
            for (String pkg : appRules.keySet()) {
                if (appRules.get(pkg).isCurrentlyBlocked) activeBlocks.add(pkg);
            }

            // যদি এই মুহূর্তে কোনো অ্যাপ ব্লকিং ফেইজে না থাকে, তবে টানেল অফ থাকবে (সবার নেট চলবে)
            if (activeBlocks.isEmpty()) {
                if (vpn != null) { vpn.close(); vpn = null; }
                showNotif("Apps are in allowed phase...");
                return; 
            }

            if (vpn != null) vpn.close();
            Builder b = new Builder().setSession("NetBlocker").addAddress("10.0.0.2", 32).addRoute("0.0.0.0", 0);

            for (String pkg : activeBlocks) { try { b.addAllowedApplication(pkg); } catch(Exception e) {} }
            try { b.addDisallowedApplication(getPackageName()); } catch(Exception e) {}

            vpn = b.establish();
            showNotif("Blocking internet for " + activeBlocks.size() + " apps...");

        } catch (Exception e) {}
    }

    private void stopVpn() {
        isRunning = false;
        try { if (vpn != null) vpn.close(); vpn = null; } catch (Exception e) {}
        stopForeground(true); stopSelf();
    }

    private void showNotif(String msg) {
        android.app.NotificationManager nm = (android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE);
        if (android.os.Build.VERSION.SDK_INT >= 26) nm.createNotificationChannel(new android.app.NotificationChannel("nb","Block",3));
        startForeground(1, new android.app.Notification.Builder(this,"nb").setSmallIcon(android.R.drawable.ic_lock_lock).setContentTitle("Network Assistant").setContentText(msg).build());
    }

    @Override public void onDestroy() { stopVpn(); super.onDestroy(); }
}
